/// Mirrors push_selected: the JS side detects the missing `rows` field
/// and applies the status without rebuilding the result list.
fn push_status(webview: &Option<WebView>, state: &Arc<Mutex<ShimState>>) {
    let Some(wv) = webview else { return };
    let status = state
        .lock()
        .ok()
        .map(|s| s.status_text.clone())
        .unwrap_or_default();
    let json = serde_json::json!({ "status": status }).to_string();
    post_json(&wv, &json);
}

fn focus_input(webview: &Option<WebView>) {
    if let Some(wv) = webview {
        // DOM focus alone (`input.focus()`) does not move WebView2's native
        // controller focus. On a fresh show, Windows can therefore deliver
        // the first WM_CHAR to the host/previous focus target and play the
        // system error sound. Move native keyboard focus into WebView2 first,
        // then focus the editable search element inside the page.
        if let Err(error) = wv.focus() {
            crate::runtime::log_info(&format!("[nex] WebView native focus failed: {error}"));
        }
        let _ = wv.evaluate_script("window.nex&&window.nex.focus()");
    }
}

/// Serialize the overlay state into lightweight JSON without icon data.
/// Icon fields contain only the file path (used as a JS cache key).
fn snapshot_state_json(s: &ShimState, show_pending: bool) -> String {
    snapshot_state_with_transparency(
        s,
        show_pending,
        crate::overlay::platform::transparency_enabled()
            && !crate::overlay::refraction::glass_failed(),
    )
}

fn snapshot_state_with_transparency(s: &ShimState, show_pending: bool, transparent: bool) -> String {
    let background = if !transparent && !s.panel_background.is_opaque() {
        if s.theme == Theme::Light { "white" } else { "black" }
    } else { s.panel_background.as_str() };
    static LENS_CLIP: std::sync::LazyLock<String> = std::sync::LazyLock::new(crate::overlay::refraction::lens_clip_css);
    let rows: Vec<serde_json::Value> = s
        .rows
        .iter()
        .map(|r| {
            let role = match r.role {
                OverlayRowRole::Header => "header",
                OverlayRowRole::Status => "status",
                OverlayRowRole::Calculator => "calculator",
                OverlayRowRole::QuickLaunch => "quick_launch",
                OverlayRowRole::ShowAllApps => "show_all_apps",
                OverlayRowRole::ClipboardHistory => "clipboard_history",
                OverlayRowRole::TopHit | OverlayRowRole::Item => "item",
            };
            let selectable = matches!(
                r.role,
                OverlayRowRole::Item
                    | OverlayRowRole::TopHit
                    | OverlayRowRole::Calculator
                    | OverlayRowRole::QuickLaunch
                    | OverlayRowRole::ShowAllApps
                    | OverlayRowRole::ClipboardHistory
            );
            let icon = if r.icon_path.is_empty() {
                serde_json::Value::Null
            } else {
                serde_json::Value::String(r.icon_path.clone())
            };
            // r.icon_path carries the real executable/filesystem path.
            // r.path is the display subtitle (publisher name for UWP apps).
            // Start-menu shortcuts arrive as shell:AppsFolder\{GUID}\… URIs;
            // clients launching / copying / locating files need the real
            // path when one exists.
            let raw_target = r.icon_path.trim().to_string();
            let resolved = if raw_target.is_empty() {
                None
            } else {
                crate::action_executor::resolve_shell_appsfolder_path(&raw_target)
            };
            let file_path = if raw_target.is_empty() {
                serde_json::Value::Null
            } else {
                serde_json::Value::String(resolved.unwrap_or(raw_target))
            };
            let tile_size = r.tile_size.as_ref().map(|t| match t {
                TileSize::Small => "small",
                TileSize::Medium => "medium",
                TileSize::Large => "large",
            });
            serde_json::json!({
                "role": role,
                "title": r.title,
                "subtitle": r.path,
      }

      if (state.theme) document.documentElement.dataset.theme = state.theme;

      // Panel background: opaque black/white paint solid and force the
      // matching palette (light text can't survive a white panel);
      // glass follows the system theme untouched.
      if (typeof state.panelBackground === "string") {
        const root = document.documentElement;
        root.classList.toggle("bg-black", state.panelBackground === "black");
        root.classList.toggle("bg-white", state.panelBackground === "white");
        if (state.panelBackground === "white") root.dataset.theme = "light";
        else if (state.panelBackground === "black") root.dataset.theme = "dark";
      }

      // System accent (DWM AccentColor) → CSS var; falls back to theme palette.
      if (state.accent) {
        document.documentElement.style.setProperty("--accent", state.accent);
      }

      // Toggle grid/list layout based on Rust config
      if (typeof state.gridView === "boolean") {
        list.classList.toggle("grid-view", state.gridView);
      }

      // Toggle bento view for clipboard history
      if (typeof state.bentoView === "boolean") {
        list.classList.toggle("bento-view", state.bentoView);
      }

      // Only overwrite the input if Rust changed it out from under us
      // (e.g. clear on hide, quick-shortcut expansion).
      if (typeof state.query === "string") {
        let display = state.query;
        let wasCmd = inCommandMode;
        if (display.startsWith("@") || display.startsWith(">")) {
          inCommandMode = true;
          display = display.slice(1);
        } else {
          inCommandMode = false;
        }
        if (wasCmd !== inCommandMode) updateSearchIcon();
        if (display !== input.value) {
          queryEcho = display;
          input.value = display;
        }
      }

      // Command-mode autofill title pushed by Rust (null outside
      // command mode). renderCompletion gates it against the typed
      // text, so stale values can never overwrite the input.
      completion = typeof state.completion === "string" ? state.completion : "";

      // Update availability: show/hide update notice. Update and
      // What's New are independent pills now (see syncUpdateNotice).
      if (typeof state.updateAvailable === "boolean" || typeof state.whatsNewPending !== "undefined") {
        if (typeof state.updateAvailable === "boolean") {
          updateAvailable = state.updateAvailable;
        }
        if (typeof state.whatsNewPending !== "undefined") {
          whatsNewPending = typeof state.whatsNewPending === "string" ? state.whatsNewPending : null;
        }
        syncUpdateNotice();
      }

      // A hide push means a fresh show comes next: never resume into
      // the What's New view, always back to search.
      if (state.overlayVisible === false && whatsNewOpen) {
        closeWhatsNew();
      }

      // The show push arrives before the panel is revealed: the palette
      // it carries is the first frame painted, so it must not ease.
      const showPush = state.overlayVisible === true && !overlayVisible;
      if (typeof state.overlayVisible === "boolean") {
        overlayVisible = state.overlayVisible;
      }
      // Every show starts on All: the tab is a within-session filter, not
      // a remembered preference.
      if (showPush && activeTab !== "all") {
        activeTab = "all";
        syncTabButtons();
      }
      // The remembered pointer position only describes the pointer while
      // it is over the panel. If the show finds it elsewhere, drop it:
      // row hover fires on mousemove alone, and recalling a position from
      // the last session would select a row nobody is pointing at.
      if (showPush && state.pointerOverPanel === false) {
        lastMouseX = -1;
        lastMouseY = -1;
      }

      // Native glass below the page: drop painted backgrounds so the
      // refracted layer shows through instead of acrylic.
      if (typeof state.glassNative === "boolean") {
        document.documentElement.classList.toggle("glass-native", state.glassNative);
      }
      if (typeof state.glassClip === "string") {
        document.documentElement.style.setProperty("--glass-clip", state.glassClip);
