    pub fn create_for_window(
        main_sys: isize,
        max_w_px: u32,
        max_h_px: u32,
        proxy: EventLoopProxy<UiCommand>,
    ) -> Option<GlassLayer> {
        if !enabled() {
            crate::logging::info("[nex][refract] disabled by environment — acrylic path");
            return None;
        }
