fn apply_window_chrome(window: &Window, state: &Arc<Mutex<ShimState>>, suppress_border: bool) -> bool {
    let (dark, glass_native) = state
        .lock()
        .map(|s| (s.theme == Theme::Dark, s.glass_native))
