/// state as the final operation before reveal/resize.
fn sync_window_frame(window: &Window, state: &Arc<Mutex<ShimState>>, suppress_border: bool) {
    let (dark, glass_native) = state
        .lock()
        .map(|s| (s.theme == Theme::Dark, s.glass_native))
        .unwrap_or((true, false));
    let opaque_panel = effective_panel_mode(state).is_opaque();
    sync_window_frame_style(window, dark, glass_native, opaque_panel, suppress_border);
}

fn sync_window_frame_if_mode_changed(
    window: &Window,
    state: &Arc<Mutex<ShimState>>,
    suppress_border: bool,
) {
    let opaque_panel = effective_panel_mode(state).is_opaque();
    let desired = if opaque_panel { 1 } else { 0 };
    let applied = APPLIED_OPAQUE_PANEL.load(Ordering::SeqCst);
    if applied != desired {
        sync_window_frame(window, state, suppress_border);
    }
}

fn sync_window_frame_style(
    window: &Window,
    dark: bool,
    glass_native: bool,
    opaque_panel: bool,
    suppress_border: bool,
) {
    let hwnd = window.hwnd() as HWND;
    let immersive_dark = i32::from(dark);
    let rounded_corners = if glass_native && !opaque_panel {
        windows_sys::Win32::Graphics::Dwm::DWMWCP_DONOTROUND
    } else {
        windows_sys::Win32::Graphics::Dwm::DWMWCP_ROUND
    };

    // Opaque panels can use one native owner for both the outline and the
    // rounded silhouette. Probe both DWM attributes before removing the
    // hard GDI regions; older Windows builds keep the CSS + region fallback.
    let opaque_dwm_candidate = if opaque_panel {
        let no_border = 0xFFFFFFFE_u32;
        let corners_supported =
            set_dwm_attribute(hwnd, DWMWA_WINDOW_CORNER_PREFERENCE, &rounded_corners);
        let border_supported = set_dwm_attribute(
            hwnd,
            windows_sys::Win32::Graphics::Dwm::DWMWA_BORDER_COLOR,
            &no_border,
        );
        corners_supported && border_supported
    } else {
        false
    };
    let opaque_dwm_frame = if opaque_dwm_candidate {
        if sync_opaque_window_region(window, false) {
            true
        } else {
            // A stale region would prevent DWM from rounding the window.
            // Reapply the known CSS fallback if either HWND refused clearing.
            sync_opaque_window_region(window, true);
            false
        }
    } else {
        sync_opaque_window_region(window, opaque_panel);
        false
    };
    OPAQUE_DWM_FRAME_ACTIVE.store(opaque_dwm_frame, Ordering::SeqCst);
    APPLIED_OPAQUE_PANEL.store(if opaque_panel { 1 } else { 0 }, Ordering::SeqCst);

    let _ = set_dwm_attribute(hwnd, DWMWA_USE_IMMERSIVE_DARK_MODE, &immersive_dark);
    let _ = set_dwm_attribute(hwnd, DWMWA_WINDOW_CORNER_PREFERENCE, &rounded_corners);

    // Glass supplies its own edge. Opaque DWM mode uses the system border;
    // opaque fallback keeps it suppressed so it cannot double the CSS line.
    let border_color: u32 = if suppress_border
        || (opaque_panel && !opaque_dwm_frame)
        || (glass_native && !opaque_panel)
    {
        0xFFFFFFFE
    } else {
        0xFFFFFFFF
    };
    let _ = set_dwm_attribute(
        hwnd,
        windows_sys::Win32::Graphics::Dwm::DWMWA_BORDER_COLOR,
        &border_color,
    );
}

/// Install or remove the hard GDI regions used by the opaque CSS fallback.
/// Opaque WebView backgrounds are needed for ClearType, and the fallback
/// region keeps their rectangular surface inside the rounded silhouette.
fn sync_opaque_window_region(window: &Window, use_region: bool) -> bool {
    use windows_sys::Win32::Foundation::{POINT, RECT};
    use windows_sys::Win32::Graphics::Gdi::{
        ClientToScreen, CreateRoundRectRgn, DeleteObject, SetWindowRgn,
    };
    use windows_sys::Win32::UI::WindowsAndMessaging::{GetClientRect, GetWindowRect};

    let hwnd = window.hwnd() as HWND;
    let webview_hwnd = find_webview_child(window);
    if !use_region {
        let host_cleared = unsafe { SetWindowRgn(hwnd, std::ptr::null_mut(), 1) != 0 };
        let child_cleared = webview_hwnd.is_null()
            || unsafe { SetWindowRgn(webview_hwnd, std::ptr::null_mut(), 1) != 0 };
        return host_cleared && child_cleared;
    }

    let mut client_rect = RECT {
        left: 0,
        top: 0,
        right: 0,
        bottom: 0,
    };
    if unsafe { GetClientRect(hwnd, &mut client_rect) } == 0 {
        return false;
    }
    let mut window_rect = RECT {
        left: 0,
        top: 0,
        right: 0,
        bottom: 0,
    };
    if unsafe { GetWindowRect(hwnd, &mut window_rect) } == 0 {
        return false;
    }
    let mut client_origin = POINT {
        x: client_rect.left,
        y: client_rect.top,
    };
    if unsafe { ClientToScreen(hwnd, &mut client_origin) } == 0 {
        return false;
    }
    let scale = window.scale_factor() as f32;
    let radius = (8.0 * scale).round() as i32;
    let width = client_rect.right - client_rect.left;
    let height = client_rect.bottom - client_rect.top;
    if width <= 0 || height <= 0 {
        return false;
    }
    // SetWindowRgn uses window-relative coordinates, while the WebView child
    // uses client-relative coordinates. Align the host region to the exact
    // client rectangle so a non-client inset cannot leave an uneven strip
    // around the child surface.
    let left = client_origin.x - window_rect.left;
    let top = client_origin.y - window_rect.top;
    // GDI regions exclude their lower/right boundary. Allow one physical
    // pixel there so the hard native clip does not trim the WebView's final
    // antialiased stroke pixel on those two edges.
    let right = left + width + 1;
    let bottom = top + height + 1;
    let mut regions_applied = true;
    unsafe {
        let region = CreateRoundRectRgn(left, top, right, bottom, radius * 2, radius * 2);
        if !region.is_null() {
            // SetWindowRgn transfers ownership only on success.
            if SetWindowRgn(hwnd, region, 1) == 0 {
                DeleteObject(region);
                regions_applied = false;
            }
        } else {
            regions_applied = false;
        }

        // The host and WRY_WEBVIEW are separate HWNDs. SetWindowRgn on the
        // host does not give the WebView child the same rounded shape; the
        // child is intentionally taller than the host so rows are already
        // rasterized when the panel grows. Clip its own surface to the host's
        // current client bounds, using the same physical-pixel radius.
        if !webview_hwnd.is_null() {
            let child_region = CreateRoundRectRgn(
                0,
                0,
                width + 1,
                height + 1,
                radius * 2,
                radius * 2,
            );
            if child_region.is_null() {
                regions_applied = false;
            } else if SetWindowRgn(webview_hwnd, child_region, 1) == 0 {
                DeleteObject(child_region);
                regions_applied = false;
            }
        }
    }
    regions_applied
}

/// Remove the caption frame tao always adds (window_state.rs forces
/// WS_CAPTION on every window). While the host was never shown, DWM still
/// composes that frame even with `DWMWA_BORDER_COLOR=NONE`: first as a
/// rounded ~2px ring, and once the border color is suppressed as a dark
/// 1px top line (`DWMWA_VISIBLE_FRAME_BORDER_THICKNESS=1`). Verified live:
/// stripping the caption bits + WS_POPUP removes both. The overlay is
/// decoration-less and never moves via a caption, so the style is dead
/// weight; the first show re-applies real chrome for the visible panel.
/// (tao re-derives styles on its own state syncs, but the only pre-show
/// sync happens at creation — after that the host goes cloak-on-hide,
                        // and foreground handoff run, then restore the maximum
                        // viewport and the native frame or fallback regions
                        // against final geometry before DWM composes the panel.
                        let _ = set_overlay_cloaked(hwnd, true);
                        set_webview_child_visible(&window, false);
                        window.set_visible(true);
                        let _ = set_overlay_cloaked(hwnd, true);
                        // Single activation path (helper owns foreground;
                        // local force only without helper). Request activation
                        // before uncloaking so DWM does not show Acrylic's
                        // inactive fallback on the first visible frame.
                        request_foreground(hwnd);
                        if let Some(wv) = webview.as_ref() {
                            keep_webview_viewport_max(wv);
                        }
                        sync_window_frame(&window, &state, false);
                        set_webview_child_visible(&window, true);
                        // Uncloaking can rebuild the non-client frame. Restore
                        // the DWM attributes after the region is applied, and
                        // leave this as the last geometry operation before
                        // composition.
                        set_overlay_cloaked(hwnd, false);
                        sync_window_frame(&window, &state, false);
                        OVERLAY_VISIBLE.store(true, Ordering::SeqCst);
                        // The window is really on screen now; further hotkey
                        // presses toggle/refocus through the normal paths.
                        crate::overlay_state::OverlayState::notify_show_painted();
                        // Reveal the glass before the focus work: the page is
                        // on screen now, so this only shortens the gap where
                        // the panel has no backdrop, and nothing here can put
                        // glass on screen without the page under it. Its HWND
                        // is revealed by the layer's own ack — a frame at the
                        // size the page just settled on — or right here if
                        // one for this size already landed.
                        // Parked in opaque panel modes (solid CSS covers it).
            scale: Some(scale),
            revealed: false,
        });
    }

    /// Show/hide with the panel. Cloaking remains immediate so launch and
    /// focus restoration never wait for a visual effect. Revealing does not:
    /// the cloak lifts only once the renderer has presented a frame at the
    /// panel's current size, so the first thing seen is this backdrop.
    pub fn set_visible(&self, show: bool) {
        let was_visible = self.visible.replace(show);
        if show {
            if let Some((w, h, bits)) = self.window.last_region.get() {
                self.apply_region(w, h, f64::from_bits(bits));
            }
        } else if was_visible {
            unsafe { windows_sys::Win32::Graphics::Gdi::SetWindowRgn(self.main_sys as _, std::ptr::null_mut(), 1); }
            self.window.region.set(None);
        }
        if !show {
            self.revealed.set(false);
            // A frame from the last session is not a frame for this show:
            // forgetting its size forces the reveal to wait for a present
            // made after the panel came back.
            self.window.last_frame.set(None);
            self.window.show(false);
        }
        let _ = self.tx.send(GlassConfig {
            visible: Some(show),
            main_sys: 0,
            max_wh: None,
            panel_wh: None,
            theme_dark: None,
            scale: None,
            revealed: false,
        });
    }

    /// Tell the renderer a show is coming without revealing the window:
    /// the panel is only revealed on its first paint, and by then the
    /// worker has re-presented the held mirror, so the uncloak carries
    /// current pixels instead of the last session's.
    pub fn prepare_show(&self) {
        if let Some((w, h, bits)) = self.window.last_region.get() {
            self.apply_region(w, h, f64::from_bits(bits));
        }
        let _ = self.tx.send(GlassConfig {
            visible: Some(true),
            main_sys: 0,
            max_wh: None,
            panel_wh: None,
            theme_dark: None,
            scale: None,
            revealed: false,
        });
    }

    /// Text theme. Seeds the material (light surface + dark text, or
    /// the reverse) until a captured frame can decide from the backdrop
    /// itself. Sent on create and on every show.
    pub fn set_theme(&self, dark: bool) {
        let _ = self.tx.send(GlassConfig {
            visible: None,
            main_sys: 0,
            max_wh: None,
            panel_wh: None,
            theme_dark: Some(dark),
            scale: None,
            revealed: false,
        });
    }

    /// Write the rounded silhouette to the main window, unless that exact
    /// size/scale is already applied (a repeated sync must not rebuild the
    /// GDI region).
    fn apply_region(&self, w: u32, h: u32, scale: f64) {
        let key = (w, h, scale.to_bits());
        if self.window.region.get() == Some(key) {
            return;
        }
        apply_lens_region(self.main_sys, w, h, scale, SILHOUETTE_GROW_PX);
        apply_glass_region(self.window.hwnd.0 as isize, w, h);
        self.window.region.set(Some(key));
    }

    /// Record that the renderer presented a frame at `w`x`h`.
    pub fn note_frame(&self, w: u32, h: u32) {
        self.window.last_frame.set(Some((w, h)));
    }

